
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_revm06_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_revm06", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.267746169790147e+00, -2.238392280901924e+00, -2.197513036351557e+00, -2.140444733608637e+00, -2.059626803988907e+00, -1.942695678831748e+00, -1.775650356678063e+00, -1.561816901675799e+00, -1.305092612587814e+00, -9.884786720142383e-01, -6.435364309942627e-01, -4.057152168766253e-01, -3.552628013775896e-01, -2.985162452962753e-01, -2.267019923684177e-01, -1.498231750040730e-01, -1.001349015814037e-01, -7.737222234598426e-02, -1.945341620024342e-02, -2.204280071775287e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


